class Solution {
  int[] b;

  public long[] countOfPairs(int n, int x, int y) {
    if (x > y) return countOfPairs(n, y, x);
    b = new int[n + 1];
    for (int i = 1; i <= n; i++) {
      add(1, i - 1, 1);
      add(1, n - i, 1);
      if (x + 1 < y) {
        if (i <= x) up(i, x, y, n);
        else if (i >= y) up(n + 1 - i, n + 1 - y, n + 1 - x, n);
        else if (i < (x + y) / 2) up2(i, x, y, n);
        else if (i > (x + y + 1) / 2) up2(n + 1 - i, n + 1 - y, n + 1 - x, n);
      }
    }
    long[] r = new long[n];
    long s = 0;
    for (int i = 0; i < n; i++) {
      s += b[i + 1];
      r[i] = s;
    }
    return r;
  }

  void add(int l, int r, int v) {
    if (l <= r) {
      b[l] += v;
      b[r + 1] -= v;
    }
  }

  void up(int i, int x, int y, int n) {
    add(y - i, n - i, -1);
    int z = y - x - 1;
    add(y - i - z, n - i - z, 1);
    int j = (x + y + 1) / 2 + 1;
    add(j - i, y - 1 - i, -1);
    add(x - i + 2, x - i + y - j + 1, 1);
  }

  void up2(int i, int x, int y, int n) {
    add(y - i, n - i, -1);
    int z = y - i - (i - x + 1);
    add(y - i - z, n - i - z, 1);
    int j = i + (y - x + 1) / 2 + 1;
    add(j - i, y - 1 - i, -1);
    add(i - x + 2, i - x + y - j + 1, 1);
  }
}
